//! `cargo xtask contributors [--max N]`: fail when `contributors/contributors.json` (the About
//! window's credits) is more than N commits behind HEAD, so a release doesn't ship a stale list.
//!
//! The file is generated by craftrules `scripts/contributors.py` and never hand-edited
//! (docs/contributors.md); `cargo xtask version set` prints the same warning.

use std::path::Path;
use std::process::Command;

/// Non-merge commits since the snapshot's `head` that still count as fresh.
const MAX_BEHIND: usize = 100;

/// The `head` commit recorded in the snapshot.
fn snapshot_head(json: &str) -> Result<String, String> {
    let v: serde_json::Value = serde_json::from_str(json).map_err(|e| format!("contributors.json: {e}"))?;
    match v.get("head").and_then(|h| h.as_str()) {
        Some(h) if !h.is_empty() && h.bytes().all(|b| b.is_ascii_hexdigit()) => Ok(h.to_string()),
        _ => Err("contributors.json has no `head` commit".into()),
    }
}

/// The snapshot's `head_date` (ISO 8601), used when `head` is not in HEAD's history.
fn snapshot_date(json: &str) -> Option<String> {
    let v: serde_json::Value = serde_json::from_str(json).ok()?;
    let d = v.get("head_date")?.as_str()?;
    (!d.is_empty() && d.bytes().all(|b| b.is_ascii_digit() || b"-:TZ+. ".contains(&b))).then(|| d.to_string())
}

/// `Some(message)` when `behind` exceeds `max`.
fn stale(behind: usize, max: usize, head: &str) -> Option<String> {
    (behind > max).then(|| {
        format!(
            "contributors/contributors.json is {behind} commits behind HEAD (snapshot at {}, limit {max}); refresh it: python3 ../../craftrules/scripts/contributors.py .",
            head.get(..9).unwrap_or(head)
        )
    })
}

/// Commits (merges excluded) between the snapshot and HEAD.
fn behind(root: &Path) -> Result<(usize, String), String> {
    let path = root.join("contributors/contributors.json");
    let json = std::fs::read_to_string(&path).map_err(|e| format!("read {}: {e}", path.display()))?;
    let head = snapshot_head(&json)?;
    let ancestor = Command::new("git")
        .current_dir(root)
        .args(["merge-base", "--is-ancestor", &head, "HEAD"])
        .status()
        .map_err(|e| format!("git merge-base: {e}"))?;
    // A squash or rebase merge drops the snapshot commit from main, so fall back to its date.
    let range = if ancestor.success() {
        vec![format!("{head}..HEAD")]
    } else {
        let date =
            snapshot_date(&json).ok_or_else(|| format!("snapshot head {head} is not in HEAD's history and contributors.json has no `head_date`"))?;
        vec![format!("--since={date}"), "HEAD".into()]
    };
    let out = Command::new("git")
        .current_dir(root)
        .args(["rev-list", "--count", "--no-merges"])
        .args(&range)
        .output()
        .map_err(|e| format!("git rev-list: {e}"))?;
    if !out.status.success() {
        return Err(format!("git rev-list {} failed: {}", range.join(" "), String::from_utf8_lossy(&out.stderr).trim()));
    }
    let n = String::from_utf8_lossy(&out.stdout).trim().parse().map_err(|e| format!("git rev-list output: {e}"))?;
    Ok((n, head))
}

/// The staleness message, if any; `Err` only when the check itself can't run.
pub fn warning(root: &Path) -> Result<Option<String>, String> {
    let (n, head) = behind(root)?;
    Ok(stale(n, MAX_BEHIND, &head))
}

pub fn run(root: &Path, args: &[&str]) -> Result<(), String> {
    let max = match args {
        [] => MAX_BEHIND,
        ["--max", n] => n.parse().map_err(|_| format!("`{n}` is not a number"))?,
        _ => return Err("usage: cargo xtask contributors [--max N]".into()),
    };
    let (n, head) = behind(root)?;
    match stale(n, max, &head) {
        Some(msg) => Err(msg),
        None => {
            println!("contributors: snapshot is {n} commits behind HEAD (limit {max})");
            Ok(())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_the_snapshot_head() {
        assert_eq!(snapshot_head(r#"{"head":"90b3c41e","contributors":[]}"#).unwrap(), "90b3c41e");
        for bad in ["{}", r#"{"head":""}"#, r#"{"head":"--all"}"#, r#"{"head":7}"#, "not json"] {
            assert!(snapshot_head(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn reads_the_snapshot_date() {
        assert_eq!(snapshot_date(r#"{"head_date":"2026-10-27T22:47:04Z"}"#).as_deref(), Some("2026-10-27T22:47:04Z"));
        for bad in ["{}", r#"{"head_date":""}"#, r#"{"head_date":"--all"}"#, "not json"] {
            assert!(snapshot_date(bad).is_none(), "{bad}");
        }
    }

    #[test]
    fn warns_only_past_the_limit() {
        assert!(stale(100, 100, "90b3c41eec69").is_none());
        let msg = stale(101, 100, "90b3c41eec69").unwrap();
        assert!(msg.contains("101 commits behind") && msg.contains("90b3c41ee") && msg.contains("contributors.py"));
    }
}
